import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    # The optimal value will be the smallest non-negative result of n mod k
    # which can be either n % k or k - (n % k) if n % k is not zero.
    r = n % k
    if r == 0:
        print(0)
    else:
        print(min(r, k - r))

if __name__ == "__main__":
    solve()
